import { installment, schedule, ledger, nextDue, addMonths, today, validDate, previewPayment } from './finance.mjs';
import { emptyWorkspace, validateWorkspace, archiveClient, deleteClient, deleteLoan, editLoan, recentLoans, loansAcceptingPayments } from './store.mjs';
import * as backend from './backend.mjs';
import{parseCOP,formatCOP,handleMoneyInput}from'./money-input.mjs';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(Math.round(v));
const date=v=>new Intl.DateTimeFormat('es-CO',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(v+'T12:00:00Z'));
const uid=()=>Array.from(crypto.getRandomValues(new Uint8Array(16)),v=>v.toString(16).padStart(2,'0')).join('');
const paths={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87"/><circle cx="9" cy="7" r="4"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>',wallet:'<path d="M20 8V5a2 2 0 0 0-2-2H5a3 3 0 0 0 0 6h16v11H5a3 3 0 0 1-3-3V6"/><path d="M21 12h-6v5h6"/><path d="M17 14.5h.01"/>',arrows:'<path d="M3 7h17m-4-4 4 4-4 4M21 17H4m4-4-4 4 4 4"/>',settings:'<path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/><circle cx="12" cy="12" r="7"/><circle cx="12" cy="12" r="3"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',up:'<path d="m3 17 6-6 4 4 8-11m-6 0h6v6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18m-12 4h.01M12 15h.01M15 15h.01"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v5m0-9h.01"/>',back:'<path d="M19 12H5m6-6-6 6 6 6"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M8 13h8M8 17h5"/>',shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6z"/><path d="m8 12 3 3 5-6"/>'};
const icon=k=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[k]||paths.file}</svg>`;
let data=emptyWorkspace(),revision=0,user=null,busy=false,authBusy=false,recovery=false,query='',filter='activos',pendingImport;
let profile=null;
const displayName=()=>profile?.preferred_name||'Crispy';
let passwordMode='recovery',passwordUser=null,authLinkMode=null,booting=true;
const cache=new Map();
function state(l,asOf=today()){const key=l.id+'|'+asOf;if(!cache.has(key))cache.set(key,ledger(l,data.payments,asOf));return cache.get(key);}
function client(id){return data.clients.find(c=>c.id===id);}
function loan(id){return data.loans.find(l=>l.id===id);}
function initials(name){return name.trim().split(/\s+/).slice(0,2).map(n=>n[0]).join('').toUpperCase();}
function person(c,i=0,sub=''){return `<span class="person"><span class="person-avatar ${['','blue','peach','lavender'][i%4]}">${esc(initials(c.name))}</span><span><strong>${esc(c.name)}</strong><small>${esc(sub||c.phone||'Sin teléfono')}${c.archivedAt?' · Archivado':''}</small></span></span>`;}
function button(label,action,kind='',ico='',attrs=''){return `<button type="button" class="btn ${kind}" data-action="${action}" ${attrs}>${ico?icon(ico):''}${label}</button>`;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),5500);}
function route(){const[page='inicio',id]=location.hash.slice(1).split('/');return{page,id};}
function go(hash){if(location.hash==='#'+hash)render();else location.hash=hash;}
function totals(loans=data.loans){return loans.reduce((t,l)=>{const a=state(l);return{principal:t.principal+l.principal,balance:t.balance+a.balance,interest:t.interest+a.paidInterest,paid:t.paid+a.paidPrincipal,late:t.late+a.paidLate,lateDue:t.lateDue+a.lateDue};},{principal:0,balance:0,interest:0,paid:0,late:0,lateDue:0});}
function heading(title,subtitle,buttons='',eyebrow='TU CARTERA, EN ORDEN'){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="buttons">${buttons}</div></div>`;}
function stats(cards){return `<div class="stats">${cards.map(c=>`<div class="stat"><div class="stat-top"><span>${c.label}</span><span class="stat-icon">${icon(c.icon)}</span></div><div class="money">${c.value}</div><div class="stat-foot">${c.foot}</div></div>`).join('')}</div>`;}
function empty(title,text){return `<div class="empty">${icon('file')}<strong>${title}</strong>${text}</div>`;}
function badge(l){const a=state(l);return !a.remainingTotal?'<span class="badge blue">Finalizado</span>':a.overdueDays?`<span class="badge orange">${a.overdueDays} días de mora</span>`:'<span class="badge">En curso</span>';}
function clientBadge(c){if(c.archivedAt)return '<span class="badge gray">Archivado</span>';const ls=data.loans.filter(l=>l.clientId===c.id);if(!ls.length)return '<span class="badge gray">Sin préstamos</span>';const days=Math.max(0,...ls.map(l=>state(l).overdueDays));return days?`<span class="badge orange">${days} días de mora</span>`:ls.some(l=>state(l).remainingTotal)?'<span class="badge">Activo</span>':'<span class="badge blue">Al día</span>';}
function clientTable(list){return `<div class="table-wrap"><table><thead><tr><th>CLIENTE</th><th>SALDO CAPITAL</th><th>ESTADO</th><th>ACCIONES</th></tr></thead><tbody>${list.map((c,i)=>{const ls=data.loans.filter(l=>l.clientId===c.id);return `<tr><td>${person(c,i,`${ls.length} préstamo${ls.length!==1?'s':''}`)}</td><td class="cell-money">${money(totals(ls).balance)}</td><td>${clientBadge(c)}</td><td><div class="row-actions">${button('Consultar','client','small','',`data-id="${esc(c.id)}"`)}${button(c.archivedAt?'Restaurar':'Archivar',c.archivedAt?'restore-client':'archive-client','small ghost','',`data-id="${esc(c.id)}"`)}${button('Eliminar','delete-client','small danger','',`data-id="${esc(c.id)}"`)}</div></td></tr>`;}).join('')}</tbody></table></div>`;}
function upcoming(){return data.loans.map(l=>({loan:l,due:state(l).next})).filter(x=>x.due).sort((a,b)=>a.due.date.localeCompare(b.due.date));}
function receiptFor(p){return state(loan(p.loanId)).receipts.find(r=>r.id===p.id);}
function overview(){const t=totals(),active=data.loans.filter(l=>state(l).remainingTotal>0),due=upcoming(),clients=data.clients.filter(c=>!c.archivedAt);return heading(`Hola, ${esc(displayName())} <span style="font-size:23px;color:#b8c78e">✦</span>`,'Tus acuerdos, tus pagos y lo que viene.',button('Descargar respaldo','export','secondary-action','download')+button('Nuevo cliente','new-client','primary','plus'))+`<section class="hero"><div class="hero-copy"><div class="eyebrow">MENOS ENREDOS. MÁS TRANQUILIDAD.</div><h2>Tus cuentas claras,<br><span>tus metas más cerca.</span></h2><p>Clientes, préstamos y abonos. Todo en un solo lugar.</p><div class="hero-chip"><i></i>${active.length} préstamos en curso · ${clients.length} clientes activos</div></div><div class="hero-summary"><div class="hero-label">${icon('wallet')} Capital por recuperar</div><div class="money">${money(t.balance)}</div><small>No incluye intereses ni recargos pendientes</small></div></section>`+stats([{label:'Capital desembolsado',value:money(t.principal),icon:'wallet',foot:'Incluye clientes archivados'},{label:'Capital recuperado',value:money(t.paid),icon:'arrows',foot:'Abonos aplicados automáticamente'},{label:'Intereses recibidos',value:money(t.interest),icon:'up',foot:'Separados del capital y la mora'},{label:'Mora recibida',value:money(t.late),icon:'clock',foot:`Recargo pendiente: ${money(t.lateDue)}`}])+`<div class="main-grid"><section class="panel"><div class="panel-heading"><div><h2>Tus clientes</h2><p>Cada historia, con sus cuentas claras.</p></div>${button('Ver todos ↗','clients','link')}</div>${clients.length?clientTable(clients.slice(0,5)):empty('Tu primer cliente empieza aquí','Agrega una persona y registra su primer préstamo.')}<div class="panel-foot"><span>${clients.length} clientes activos</span><button type="button" data-action="new-client">+ Agregar cliente</button></div></section><section class="panel"><div class="panel-heading"><div><h2>Cuotas por atender</h2><p>Capital, intereses y recargos a la fecha.</p></div><span class="tag">${due.length} préstamos</span></div><div class="payment-list">${due.slice(0,4).map(x=>{const d=new Date(x.due.date+'T12:00:00Z');return `<div class="payment-item"><span class="date-tile"><b>${d.getUTCDate()}</b><small>${d.toLocaleDateString('es-CO',{month:'short',timeZone:'UTC'}).replace('.','').toUpperCase()}</small></span><span class="payment-info"><strong>${esc(client(x.loan.clientId).name.split(' ').slice(0,2).join(' '))}</strong><small>Cuota ${x.due.number} de ${x.loan.months}</small></span><span class="payment-value"><strong>${money(x.due.remaining)}</strong><small>${x.due.daysLate?x.due.daysLate+' días de atraso':'Programada'}</small></span><button type="button" class="row-arrow" data-action="client" data-id="${esc(x.loan.clientId)}" aria-label="Ver préstamo">${icon('arrow')}</button></div>`;}).join('')||empty('Todo por empezar','Los préstamos pendientes aparecerán aquí.')}</div><div class="subtle-note">${icon('info')}<span>La mora se calcula por días sobre el capital vencido, con la tasa acordada en cada préstamo.</span></div></section></div><div class="bottom-grid"><section class="panel"><div class="panel-heading"><div><h2>Últimos movimientos</h2><p>El historial de tu cartera.</p></div>${button('Ver historial ↗','payments','link')}</div><div class="activity-list">${data.payments.filter(p=>!p.reversed).slice().sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt)).slice(0,3).map(p=>`<div class="activity"><span class="activity-icon">${icon('check')}</span><div class="activity-text"><strong>Abono de ${esc(client(loan(p.loanId).clientId).name.split(' ')[0])}</strong><small>${date(p.date)} · ${esc(p.method)}</small></div><span class="activity-value">+ ${money(p.amount)}</span></div>`).join('')||empty('Aún no hay abonos','Aquí verás los pagos que registres.')}</div></section><section class="panel"><div class="panel-heading"><div><h2>Así va tu capital</h2><p>El recorrido de tu dinero.</p></div><span class="stat-icon">${icon('up')}</span></div><div class="portfolio"><div class="portfolio-total"><strong>${t.principal?Math.round(t.paid/t.principal*100):0}%</strong><small>del capital recuperado</small></div><div class="portfolio-bar"><span style="width:${t.principal?t.paid/t.principal*100:0}%"></span><span style="width:${t.principal?t.balance/t.principal*100:0}%"></span></div><div class="legend"><div><i></i>Recuperado<b>${money(t.paid)}</b></div><div><i></i>Pendiente<b>${money(t.balance)}</b></div><div><i></i>Mora pendiente<b>${money(t.lateDue)}</b></div></div></div></section></div>`;}
function clientsView(){let list=data.clients.filter(c=>(c.name+' '+c.phone).toLocaleLowerCase().includes(query.toLocaleLowerCase()));list=list.filter(c=>filter==='todos'||(filter==='archivados'?!!c.archivedAt:!c.archivedAt));return heading('Tus clientes','Una ficha individual para cada persona.',button('Nuevo cliente','new-client','primary','plus'))+`<div class="toolbar"><label class="search">${icon('search')}<input id="search" aria-label="Buscar cliente" placeholder="Buscar por nombre o teléfono…" value="${esc(query)}"></label><div class="tabs">${[['activos','Activos'],['archivados','Archivados'],['todos','Todos']].map(([id,label])=>`<button type="button" data-action="filter" data-value="${id}" class="${filter===id?'selected':''}">${label}</button>`).join('')}</div></div><section class="panel">${list.length?clientTable(list):empty('No hay clientes para mostrar','Prueba otra búsqueda o agrega un cliente.')}<div class="panel-foot">${list.length} resultados</div></section>`;}
function loansView(){const list=recentLoans(data.loans).filter(l=>(client(l.clientId).name+' '+l.id).toLocaleLowerCase().includes(query.toLocaleLowerCase())).filter(l=>filter==='todos'||(filter==='finalizados'?!state(l).remainingTotal:state(l).remainingTotal>0));return heading('Préstamos','Los acuerdos, sus cuotas y sus fechas.',button('Nuevo préstamo','new-loan','primary','plus'))+`<div class="toolbar"><label class="search">${icon('search')}<input id="search" aria-label="Buscar préstamo" placeholder="Buscar por cliente…" value="${esc(query)}"></label><div class="tabs">${[['activos','En curso'],['finalizados','Finalizados'],['todos','Todos']].map(([id,label])=>`<button type="button" data-action="filter" data-value="${id}" class="${filter===id?'selected':''}">${label}</button>`).join('')}</div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>CLIENTE</th><th>CAPITAL PENDIENTE</th><th>INTERÉS / MORA MENSUAL</th><th>CUOTAS</th><th>ESTADO</th><th></th></tr></thead><tbody>${list.map((l,i)=>`<tr><td>${person(client(l.clientId),i,date(l.start))}</td><td class="cell-money">${money(state(l).balance)}</td><td>${l.rate}% / ${l.lateRate}%</td><td>${l.months} mensuales</td><td>${badge(l)}</td><td><div class="row-actions">${button('Consultar','client','small','',`data-id="${esc(l.clientId)}"`)}${button('Editar','edit-loan','small ghost','',`data-id="${esc(l.id)}"`)}${button('Eliminar','delete-loan','small danger','',`data-id="${esc(l.id)}"`)}</div></td></tr>`).join('')}</tbody></table></div>${!list.length?empty('Sin préstamos para mostrar','Registra un préstamo o revisa los filtros.'):''}</section>`;}
function paymentsTable(list,showClient=true){return `<div class="table-wrap"><table><thead><tr><th>FECHA</th>${showClient?'<th>CLIENTE</th>':''}<th>CAPITAL</th><th>INTERÉS</th><th>MORA</th><th>TOTAL</th><th>ATRASO AL PAGAR</th><th></th></tr></thead><tbody>${list.slice().sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt)).map(p=>{const r=receiptFor(p);return `<tr ${p.reversed?'class="reversed"':''}><td>${date(p.date)}</td>${showClient?`<td>${esc(client(loan(p.loanId).clientId).name)}</td>`:''}<td>${r?money(r.capital):'—'}</td><td>${r?money(r.interest):'—'}</td><td>${r?money(r.late):'—'}</td><td class="cell-money">${money(p.amount)}</td><td>${p.reversed?'<span class="badge gray">Anulado</span>':(r.daysLate?r.daysLate+' días':'A tiempo')}</td><td>${button('Detalle','payment-detail','small ghost','',`data-id="${esc(p.id)}"`)}</td></tr>`;}).join('')}</tbody></table></div>`;}
function paymentsView(){const list=data.payments.filter(p=>(client(loan(p.loanId).clientId).name+' '+p.method).toLocaleLowerCase().includes(query.toLocaleLowerCase()));return heading('Movimientos','Un valor por abono. El desglose se calcula por ti.',button('Registrar abono','new-payment','primary','plus'))+`<div class="toolbar"><label class="search">${icon('search')}<input id="search" aria-label="Buscar movimiento" placeholder="Buscar por cliente o medio de pago…" value="${esc(query)}"></label>${button('Exportar CSV','csv','','download')}</div><section class="panel">${list.length?paymentsTable(list):empty('Todavía no hay abonos','Cuando recibas un pago, regístralo aquí.')}</section>`;}
function clientView(id){const c=client(id);if(!c)return empty('Cliente no encontrado','Vuelve a la lista de clientes.');const ls=recentLoans(data.loans.filter(l=>l.clientId===id)),t=totals(ls),ps=data.payments.filter(p=>ls.some(l=>l.id===p.loanId));return `<button type="button" class="back" data-action="clients">${icon('back')} Volver a clientes</button><div class="page-heading"><div class="client-head"><span class="person-avatar">${esc(initials(c.name))}</span><div><div class="eyebrow">HOJA DE VIDA DEL CLIENTE</div><h1>${esc(c.name)}</h1><p>${esc(c.phone||'Sin teléfono')} · Desde ${date(c.createdAt)}${c.archivedAt?' · Archivado':''}</p></div></div><div class="buttons">${button('Editar ficha','edit-client','','file',`data-id="${esc(id)}"`)}${!c.archivedAt?button('Nuevo préstamo','new-loan','primary','plus',`data-id="${esc(id)}"`):''}</div></div>`+stats([{label:'Capital desembolsado',value:money(t.principal),icon:'wallet',foot:`${ls.length} préstamo${ls.length!==1?'s':''} registrado${ls.length!==1?'s':''}`},{label:'Capital pendiente',value:money(t.balance),icon:'clock',foot:'Sin intereses ni recargos'},{label:'Intereses recibidos',value:money(t.interest),icon:'up',foot:'Distribuidos por cuota'},{label:'Mora recibida',value:money(t.late),icon:'calendar',foot:`Recargo pendiente: ${money(t.lateDue)}`}])+`<div class="detail-grid"><div class="detail-cards">${ls.map((l,i)=>{const a=state(l);return `<section class="panel"><div class="loan-summary"><div class="loan-top"><div><strong>Préstamo ${String(data.loans.filter(x=>x.clientId===id).findIndex(x=>x.id===l.id)+1).padStart(2,'0')}</strong><small>Desembolsado el ${date(l.start)}</small></div>${badge(l)}</div><div class="loan-numbers"><div><small>MONTO INICIAL</small><strong>${money(l.principal)}</strong></div><div><small>CAPITAL PENDIENTE</small><strong>${money(a.balance)}</strong></div><div><small>CUOTA MENSUAL</small><strong>${money(installment(l.principal,l.rate,l.months))}</strong></div></div><div class="progress"><span style="width:${a.paidPrincipal/l.principal*100}%"></span></div><div class="progress-label"><span>${Math.round(a.paidPrincipal/l.principal*100)}% del capital recuperado</span><span>${l.months} cuotas · ${l.rate}% mensual</span></div><div class="loan-alert"><span>Pendiente a hoy <b>${money(a.amountDue)}</b></span><span>Recargo pendiente <b>${money(a.lateDue)}</b></span></div><p class="method-label">Mora: ${l.lateRate}% mensual sobre capital vencido, por días / 30. ${esc(l.note)}</p><div class="loan-actions">${a.remainingTotal?button('Registrar abono','new-payment','primary','plus',`data-id="${esc(l.id)}"`):'<span class="badge blue">Finalizado</span>'}${button('Ver cuotas','schedule','','calendar',`data-id="${esc(l.id)}"`)}${button('Editar crédito','edit-loan','ghost','',`data-id="${esc(l.id)}"`)}${button('Eliminar crédito','delete-loan','danger','',`data-id="${esc(l.id)}"`)}</div></div></section>`;}).join('')||`<section class="panel">${empty('Su historia empieza aquí','Agrega el primer préstamo de este cliente.')}</section>`}<section class="panel"><div class="panel-heading"><div><h2>Historial de abonos</h2><p>Capital, intereses y mora, calculados por fecha.</p></div><span class="tag">${ps.filter(p=>!p.reversed).length} abono${ps.filter(p=>!p.reversed).length!==1?'s':''}</span></div>${ps.length?paymentsTable(ps,false):empty('Todavía no hay abonos','Registra el primer pago cuando lo recibas.')}</section></div><aside class="panel" style="align-self:start"><div class="panel-heading"><h2>Datos del cliente</h2></div><div class="info-list"><div><small>NOMBRE COMPLETO</small><p>${esc(c.name)}</p></div><div><small>TELÉFONO</small><p>${esc(c.phone||'Sin registrar')}</p></div><div><small>OBSERVACIONES</small><p>${esc(c.note||'Sin observaciones.')}</p></div><div><small>ESTADO</small>${clientBadge(c)}</div><div class="client-controls">${button(c.archivedAt?'Restaurar cliente':'Archivar cliente',c.archivedAt?'restore-client':'archive-client','','',`data-id="${esc(id)}"`)}${button('Eliminar cliente','delete-client','danger','',`data-id="${esc(id)}"`)}</div></div><div class="financial-note">Archivar conserva los préstamos, los abonos y los saldos. Eliminar borra esta ficha y todos sus préstamos y abonos, después de tu confirmación.</div></aside></div>`;}
function nameForm(){return `<form id="profile-form">${field('preferredName','¿Cómo quieres que te llame?',input('preferredName',`required maxlength="40" autocomplete="nickname" value="${esc(profile?.preferred_name||'')}" placeholder="Tu nombre preferido"`))}<p class="method-label">Este nombre aparecerá en tu saludo y en tu perfil.</p><div id="form-error"></div><button type="submit" class="btn primary">Guardar mi nombre</button></form>`;}
function customerView(){return heading(`Hola, ${esc(displayName())}`,'Bienvenido a Crispy Crédito.','','TU CUENTA DE CLIENTE')+`<section class="panel"><div class="panel-heading"><h2>Tu espacio de cliente</h2><span class="badge blue">Cuenta creada</span></div><div class="settings-body"><p>Tu acceso está listo. La consulta de préstamos e historial de cliente estará disponible en una próxima actualización.</p><p>Tu cuenta todavía no está vinculada a una ficha de cliente. Crear una cuenta no enlaza ni muestra registros financieros automáticamente.</p>${button('Personalizar mi nombre','my-space','primary')}${button('Cerrar sesión','logout','ghost')}</div></section>`;}
function customerSettings(){return heading('Mi espacio','Tu nombre y tu acceso.','','CONFIGURACIÓN')+`<section class="panel"><div class="panel-heading"><h2>Tu cuenta de cliente</h2></div><div class="settings-body"><p>${esc(user.email)}</p>${nameForm()}${button('Cerrar sesión','logout','ghost')}</div></section>`;}
function settingsView(){return heading('Tu espacio','Tu acceso, tus reglas y tus respaldos.','','CONFIGURACIÓN')+`<div class="settings-grid"><section class="panel"><div class="panel-heading"><h2>Tu cuenta</h2>${icon('shield')}</div><div class="settings-body"><p><strong>${esc(user?.email||'')}</strong><br>Los registros se guardan en tu proyecto de Supabase. Tu cuenta tiene permiso de administrador.</p>${nameForm()}${button('Actualizar registros','reload','','arrows')}${button('Cerrar sesión','logout','ghost')}<p class="method-label">Al salir se retiran los registros de la pantalla. No se guarda una copia de la cartera en el almacenamiento local del navegador.</p></div></section><section class="panel"><div class="panel-heading"><h2>Respaldos</h2>${icon('download')}</div><div class="settings-body"><p>Descarga una copia de tus registros. También puedes importar un respaldo compatible de la versión anterior.</p>${button('Descargar respaldo','export','primary','download')}${button('Importar respaldo','import','','file')}<input id="import-file" type="file" accept="application/json,.json" hidden><p class="method-label">Importar reemplaza tu cartera completa, después de tu confirmación. Los abonos antiguos mantienen su distribución original; no se les agrega mora retroactiva.</p></div></section><section class="panel"><div class="panel-heading"><h2>Cómo se aplican los pagos</h2></div><div class="settings-body"><p>Se atiende primero la cuota pendiente más antigua. En cada cuota se cubre el recargo de mora, después el interés corriente y finalmente el capital. El valor sobrante pasa a la siguiente cuota.</p><p>Los pagos anticipados de cuotas conservan los intereses del plan inicial; esta opción no es una liquidación anticipada ni un abono extraordinario exclusivamente a capital.</p></div></section><section class="panel"><div class="panel-heading"><h2>Días de atraso y mora</h2></div><div class="settings-body"><p>El atraso comienza el día siguiente al vencimiento. La mora es simple: capital vencido pendiente × tasa mensual / 100 × días / 30. No se cobra mora sobre intereses ni sobre recargos.</p><p>Los abonos parciales reducen la base de mora desde su fecha real. Los abonos con fecha anterior y las anulaciones recalculan cronológicamente el historial.</p></div></section></div>`;}
function render(){if(!user||!profile)return;cache.clear();const r=route(),admin=profile.role==='admin',names={inicio:'Resumen',clientes:'Clientes',prestamos:'Préstamos',movimientos:'Movimientos',configuracion:'Mi espacio',cliente:'Ficha del cliente'};$('#crumb').textContent=admin?(names[r.page]||'Resumen'):(r.page==='configuracion'?'Mi espacio':'Mi cuenta');$('#profile-email').textContent=user.email||'';$('#profile-name').textContent=displayName();$('#profile-avatar').textContent=initials(displayName());$('#top-avatar').textContent=initials(displayName());$('[aria-label="Actualizar registros"]').hidden=!admin;$('#sync-status').innerHTML=admin?'<span></span> Conectado':'<span></span> Cuenta cliente';const links=admin?[['inicio','Resumen','grid'],['clientes','Clientes','users'],['prestamos','Préstamos','wallet'],['movimientos','Movimientos','arrows'],['configuracion','Mi espacio','settings']]:[['inicio','Mi cuenta','shield'],['configuracion','Mi espacio','settings']];$('#nav').innerHTML=links.map(([id,label,ico])=>`<a class="nav-item ${r.page===id||(id==='clientes'&&r.page==='cliente')?'active':''}" href="#${id}">${icon(ico)}${label}${id==='clientes'?`<span class="nav-count">${data.clients.filter(c=>!c.archivedAt).length}</span>`:''}</a>`).join('');$('#content').innerHTML=admin?({inicio:overview,clientes:clientsView,prestamos:loansView,movimientos:paymentsView,configuracion:settingsView,cliente:()=>clientView(r.id)}[r.page]||overview)():(r.page==='configuracion'?customerSettings():customerView());}
function modal(title,subtitle,body){$('#modal-content').innerHTML=`<div class="modal-head"><div><h2>${title}</h2><p>${subtitle}</p></div><button type="button" class="icon-button" data-action="close" aria-label="Cerrar">×</button></div><div class="modal-body">${body}</div>`;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){if(!busy)$('#modal').close();}
const field=(id,label,html,full=false)=>`<div class="field ${full?'full':''}"><label for="${id}">${label}</label>${html}</div>`;
const input=(name,attrs='')=>`<input id="${name}" name="${name}" ${attrs}>`;
const actions=label=>`<div id="form-error"></div><div class="form-actions">${button('Cancelar','close')}<button class="btn primary" type="submit">${icon('check')}${label}</button></div>`;
function clientForm(id){const c=client(id);modal(c?'Editar ficha':'Un nuevo comienzo',c?'Actualiza los datos del cliente.':'Agrega una persona y organiza su historial.',`<form id="client-form" data-id="${esc(id||'')}"><div class="form-grid">${field('name','Nombre completo *',input('name',`required maxlength="100" autocomplete="name" placeholder="Ej. Laura Gómez" value="${esc(c?.name||'')}"`),true)}${field('phone','Teléfono',input('phone',`type="tel" maxlength="30" autocomplete="tel" placeholder="Ej. 300 123 4567" value="${esc(c?.phone||'')}"`),true)}${field('note','Observaciones',`<textarea id="note" name="note" maxlength="1000">${esc(c?.note||'')}</textarea>`,true)}</div>${actions(c?'Guardar cambios':'Agregar cliente')}</form>`);}
function loanForm(clientId,editId=null){
  const existing=editId?loan(editId):null;if(editId&&!existing){toast('No encontramos ese crédito.');return;}
  const eligible=data.clients.filter(c=>!c.archivedAt||c.id===existing?.clientId);
  if(!eligible.length){toast('Primero agrega o restaura un cliente.');return;}
  const selected=existing?.clientId||clientId,start=existing?.start||today(),custom=!!existing?.firstDueDate,ps=existing?data.payments.filter(p=>p.loanId===existing.id):[];
  modal(existing?'Editar crédito':'Un nuevo préstamo',existing?'Corrige los datos y revisa el plan antes de guardar.':'Define las cuotas y las tasas acordadas.',`<form id="loan-form" data-id="${esc(existing?.id||'')}"><div class="form-grid">${field('clientId','Cliente *',`<select id="clientId" name="clientId" required><option value="">Selecciona una persona</option>${eligible.map(c=>`<option value="${esc(c.id)}" ${c.id===selected?'selected':''}>${esc(c.name)}${c.archivedAt?' (archivado)':''}</option>`).join('')}</select>`,true)}${field('principal','Monto a prestar (COP) *',input('principal',`type="text" inputmode="numeric" data-money maxlength="17" required placeholder="1.000.000" value="${existing?formatCOP(existing.principal):''}"`))}${field('start','Fecha de desembolso *',input('start',`type="date" min="2000-01-01" max="2100-01-01" required value="${start}"`))}${field('months','Cuotas mensuales *',input('months',`type="number" min="1" max="120" step="1" required placeholder="6" value="${existing?.months??''}"`))}${field('rate','Interés mensual (%) *',input('rate',`type="number" min="0" max="1000" step="0.001" required placeholder="0 si no aplica" value="${existing?.rate??''}"`))}${field('lateRate','Tasa mensual de mora (%) *',input('lateRate',`type="number" min="0" max="1000" step="0.001" required placeholder="La tasa acordada; 0 si no aplica" value="${existing?.lateRate??''}"`)+'<small>Solo sobre capital vencido. Cálculo diario: tasa mensual / 30.</small>',true)}<div class="field full"><label class="check-line"><input id="customDates" name="customDates" type="checkbox" ${custom?'checked':''}> Personalizar la fecha de pago</label><p class="method-label">Por defecto, la primera cuota vence un mes después del desembolso.</p></div><div id="custom-date-field" class="field full" ${custom?'':'hidden'}><label for="firstDueDate">Primera fecha de pago *</label>${input('firstDueDate',`type="date" max="2100-12-31" value="${existing?.firstDueDate||addMonths(start,1)}" ${custom?'required':'disabled'}`)}<small>Las siguientes cuotas vencen el mismo día de cada mes. Si ese día no existe, se usa el último día del mes. Solo cambian las fechas: se conserva el interés mensual del plan.</small></div>${field('note','Observaciones del acuerdo',`<textarea id="note" name="note" maxlength="1000">${esc(existing?.note||'')}</textarea>`,true)}</div>${existing?`<div class="help-box blue">Se conservarán ${ps.length} abono(s) y su fecha real. Al cambiar las condiciones se recalculan cuotas, intereses, mora y distribución de esos pagos. Si el nuevo plan no admite un pago ya registrado, no se guardará ningún cambio.</div>`:''}<div class="help-box">Cuota mensual fija con interés sobre saldo. Por defecto, la primera cuota vence un mes después del desembolso. Tú defines las tasas del acuerdo; la aplicación no asigna un porcentaje por defecto.</div><div id="simulation" class="simulation"><div class="span">Completa monto, cuotas e interés para ver el plan.</div></div>${actions(existing?'Guardar cambios y recalcular':'Guardar préstamo')}</form>`);updateLoanDates();if(existing)updateSimulation();
}
function updateLoanDates(){const f=$('#loan-form');if(!f)return;const custom=f.elements.customDates.checked,d=f.elements.firstDueDate;$('#custom-date-field').hidden=!custom;d.disabled=!custom;d.required=custom;if(validDate(f.elements.start.value)){d.min=new Date(Date.parse(f.elements.start.value+'T12:00:00Z')+86400000).toISOString().slice(0,10);if(!custom)d.value=addMonths(f.elements.start.value,1);}}
function updateSimulation(){const f=$('#loan-form');if(!f)return;try{if(f.elements.rate.value==='')throw Error();updateLoanDates();const l={principal:parseCOP(f.elements.principal.value),months:+f.elements.months.value,rate:+f.elements.rate.value,start:f.elements.start.value||today(),...(f.elements.customDates.checked?{firstDueDate:f.elements.firstDueDate.value}:{})},q=installment(l.principal,l.rate,l.months),plan=schedule(l),total=plan.reduce((s,r)=>s+r.total,0);$('#simulation').innerHTML=`<div><small>CUOTA MENSUAL</small><strong>${money(q)}</strong></div><div><small>TOTAL DEL PLAN</small><strong>${money(total)}</strong></div><div class="span">Intereses del plan: ${money(total-l.principal)}. La última cuota se ajusta por redondeo. No incluye posibles recargos de mora.<br>Primera cuota: <b>${date(plan[0].date)}</b> · Última: <b>${date(plan.at(-1).date)}</b>.</div>`;}catch{$('#simulation').innerHTML='<div class="span">Completa monto, cuotas e interés válidos para ver el plan.</div>';}}
function paymentForm(id){const eligible=loansAcceptingPayments(data);if(!eligible.length){toast(data.loans.length?'Todos los créditos están saldados. Puedes editar un crédito si registraste un dato incorrecto.':'Primero registra un crédito para poder abonar.');return;}if(id&&!eligible.some(l=>l.id===id)){toast('Este crédito está saldado. Puedes revisar sus abonos o editar sus datos.');return;}modal('Registrar un abono','Puedes abonar antes, el día o después del vencimiento de la cuota.',`<form id="payment-form" data-payment-id="${uid()}" data-created-at="${new Date().toISOString()}"><div class="form-grid">${field('loanId','Préstamo *',`<select id="loanId" name="loanId" required>${eligible.map(l=>`<option value="${esc(l.id)}" ${l.id===id?'selected':''}>${esc(client(l.clientId).name)} · ${money(l.principal)} · ${date(l.start)}</option>`).join('')}</select>`,true)}${field('amount','Valor recibido (COP) *',input('amount','type="text" inputmode="numeric" data-money maxlength="17" required placeholder="Ej. 100.000"'),true)}${field('date','Fecha real del abono *',input('date',`type="date" max="${today()}" required value="${today()}"`))}${field('method','Medio de pago',`<select id="method" name="method"><option>Transferencia</option><option>Efectivo</option><option>Nequi</option><option>Otro</option></select>`)}${field('note','Nota o referencia',`<textarea id="note" name="note" maxlength="1000" placeholder="Referencia del pago…"></textarea>`,true)}</div><div id="payment-due" class="help-box"></div><div id="payment-summary" class="payment-preview"></div><div id="backdated-warning"></div><div class="help-box blue">Cuotas de la más antigua a la más reciente: primero mora, luego interés y después capital. El sobrante cubre la siguiente cuota, incluido su interés contractual. No se trata de un abono extraordinario a capital.</div>${actions('Guardar abono')}</form>`);updatePaymentSummary();}
function candidatePayment(f){return{id:f.dataset.paymentId,loanId:f.elements.loanId.value,amount:parseCOP(f.elements.amount.value),date:f.elements.date.value,method:f.elements.method.value,note:f.elements.note.value.trim(),createdAt:f.dataset.createdAt,reversed:false};}
function updatePaymentSummary(){const f=$('#payment-form');if(!f)return;const l=loan(f.elements.loanId.value),d=f.elements.date.value;f.elements.date.min=l.start;$('#payment-due').innerHTML='';$('#backdated-warning').innerHTML='';try{if(l.start>today()){$('#payment-due').innerHTML=`El desembolso de este crédito figura para el <b>${date(l.start)}</b>. Si ya entregaste el dinero, corrige esa fecha para registrar el abono recibido hoy. ${button('Editar fecha del crédito','edit-loan','small','',`data-id="${esc(l.id)}"`)}`;throw Error('La fecha del abono debe ser igual o posterior al desembolso.');}if(!validDate(d)||d<l.start||d>today())throw Error('Revisa la fecha del pago.');const base=state(l,d),first=base.next;$('#payment-due').innerHTML=`${d<schedule(l)[0].date?'<strong>Abono anticipado: puedes pagar aunque la primera cuota aún no venza.</strong><br>':''}<span>Total pendiente del plan: <b>${money(base.remainingTotal)}</b></span><br><span>Cuotas vencidas y de hoy: <b>${money(base.amountDue)}</b></span><br><span>${base.overdueDays} días de atraso · Recargo acumulado: <b>${money(base.lateDue)}</b></span>${first?`<br><span>Primera cuota pendiente: <b>${money(first.remaining)}</b> · vence ${date(first.date)}</span>`:''}`;const later=data.payments.some(p=>p.loanId===l.id&&!p.reversed&&p.date>d);$('#backdated-warning').innerHTML=later?'<div class="help-box">Hay pagos posteriores a esta fecha. Al guardar se recalculará su distribución y la mora en orden cronológico.</div>':'';if(!f.elements.amount.value){$('#payment-summary').innerHTML='<p class="method-label">Escribe el valor recibido para ver cómo se aplicará.</p>';return;}const p=candidatePayment(f),r=previewPayment(l,data.payments,p);$('#payment-summary').innerHTML=`<div class="split-grid"><div><small>A CAPITAL</small><strong>${money(r.capital)}</strong></div><div><small>A INTERESES</small><strong>${money(r.interest)}</strong></div><div><small>A MORA</small><strong>${money(r.late)}</strong></div></div><div class="split-footer"><span>${r.daysLate} días de atraso al pagar</span><strong>Capital restante: ${money(r.balance)}</strong></div><p class="method-label">Cuotas cubiertas total o parcialmente: ${r.allocations.map(a=>a.number).join(', ')}.</p>`;}catch(e){$('#payment-summary').innerHTML=`<div class="form-error">${esc(e.message)}</div>`;}}
function showSchedule(id){const l=loan(id),a=state(l);modal('Cuotas del préstamo',`${esc(client(l.clientId).name)} · ${l.months} cuotas · Estado al ${date(today())}`,`<p class="schedule-note">Capital, interés corriente y recargos que quedan por pagar en cada cuota. Mora simple, sin intereses sobre intereses.</p><div class="table-wrap"><table><thead><tr><th>CUOTA / VENCE</th><th>CAPITAL PEND.</th><th>INTERÉS PEND.</th><th>MORA PEND.</th><th>TOTAL PEND.</th><th>ESTADO</th></tr></thead><tbody>${a.rows.map(r=>`<tr><td>${r.number} · ${date(r.date)}</td><td>${money(r.capitalDue)}</td><td>${money(r.interestDue)}</td><td>${money(r.lateDue)}</td><td class="cell-money">${money(r.remaining)}</td><td>${!r.remaining?'<span class="badge blue">Pagada</span>':r.daysLate?`<span class="badge orange">${r.daysLate} días</span>`:'<span class="badge">Pendiente</span>'}</td></tr>`).join('')}</tbody></table></div><div class="form-actions">${button('Cerrar','close','primary')}</div>`);}
function showPayment(id){const p=data.payments.find(p=>p.id===id),l=loan(p.loanId),r=receiptFor(p);modal('Detalle del abono',esc(client(l.clientId).name),`<div class="info-list"><div><small>FECHA REAL / FECHA DE REGISTRO</small><p>${date(p.date)} / ${date(p.createdAt.slice(0,10))}</p></div><div><small>TOTAL RECIBIDO</small><p><b>${money(p.amount)}</b> · ${esc(p.method)}</p></div>${r?`<div class="split-grid"><div><small>CAPITAL</small><strong>${money(r.capital)}</strong></div><div><small>INTERESES</small><strong>${money(r.interest)}</strong></div><div><small>MORA</small><strong>${money(r.late)}</strong></div></div><div style="margin-top:20px"><small>ATRASO AL PAGAR</small><p>${r.daysLate} días${p.legacySplit?' · Distribución histórica conservada':''}</p></div>`:'<div><span class="badge gray">Abono anulado</span><p>No afecta los saldos.</p></div>'}<div><small>NOTA</small><p>${esc(p.note||'Sin observaciones.')}</p></div></div>${!p.reversed?'<div class="help-box">Anular conserva el registro y recalcula cronológicamente los pagos posteriores.</div>':''}<div class="form-actions">${button('Cerrar','close')}${!p.reversed?button('Anular abono','reverse','danger','',`data-id="${esc(p.id)}"`):''}</div>`);}
function confirmDialog(title,text,action,label,attrs=''){modal(title,text,`<div id="form-error"></div><div class="form-actions">${button('Cancelar','close')}${button(label,action,'primary','',attrs)}</div>`);}
function confirmArchive(id,restore=false){const c=client(id);confirmDialog(restore?'¿Restaurar cliente?':'¿Archivar cliente?',restore?`${esc(c.name)} volverá a la lista de clientes activos.`:`${esc(c.name)} pasará a Archivados. Su historial y sus saldos se conservarán.`,restore?'confirm-restore':'confirm-archive',restore?'Sí, restaurar':'Sí, archivar',`data-id="${esc(id)}"`);}
function deletionForm(id,formId,label){return `<form id="${formId}" data-id="${esc(id)}"><label class="check-line"><input type="checkbox" name="confirmedDelete" required checked> ${label}</label>${actions('Sí, eliminar definitivamente')}</form>`;}
function deleteClientDialog(id){const c=client(id);if(!c)return;const ls=data.loans.filter(l=>l.clientId===id),ps=data.payments.filter(p=>ls.some(l=>l.id===p.loanId));modal('¿Eliminar este cliente y su historial?',esc(c.name),`<div class="delete-warning"><strong>Se eliminarán definitivamente:</strong><p>La ficha de ${esc(c.name)}, ${ls.length} préstamo(s) y ${ps.length} abono(s), incluidos los anulados.</p><p>La cartera dejará de incluir sus saldos y movimientos. Esta acción no se puede deshacer desde la app.</p></div>${deletionForm(id,'delete-form','Confirmo eliminar este cliente y todo su historial.')}`);$('#delete-form [type="submit"]').classList.add('danger');}
function deleteLoanDialog(id){const l=loan(id);if(!l)return;const ps=data.payments.filter(p=>p.loanId===id);modal('¿Eliminar este crédito?',esc(client(l.clientId).name),`<div class="delete-warning"><strong>Crédito de ${money(l.principal)}, desembolsado el ${date(l.start)}.</strong><p>Se eliminarán este crédito y sus ${ps.length} abono(s), incluidos los anulados. El cliente y sus otros créditos se conservarán.</p><p>Esta acción no se puede deshacer desde la app.</p></div>${deletionForm(id,'delete-loan-form','Confirmo eliminar este crédito y todos sus abonos.')}`);$('#delete-loan-form [type="submit"]').classList.add('danger');}
function download(text,name,type){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function exportData(){download(JSON.stringify(data,null,2),`crispy-credito-respaldo-${today()}.json`,'application/json');toast('Respaldo descargado.');}
function exportCsv(){const quote=v=>'"'+String(v).replace(/"/g,'""')+'"',safe=v=>typeof v==='string'&&/^[=+@\-\t\r]/.test(v)?"'"+v:v;const rows=[['Fecha','Cliente','Capital COP','Intereses COP','Mora COP','Total COP','Dias atraso al pagar','Medio','Estado','Nota'],...data.payments.map(p=>{const r=receiptFor(p);return[p.date,client(loan(p.loanId).clientId).name,r?.capital??'',r?.interest??'',r?.late??'',p.amount,r?.daysLate??'',p.method,p.reversed?'Anulado':'Registrado',p.note];})];download('\uFEFF'+rows.map(r=>r.map(v=>quote(safe(v))).join(';')).join('\r\n'),`crispy-credito-movimientos-${today()}.csv`,'text/csv;charset=utf-8');}
async function mutate(change){if(busy)throw Error('Hay un guardado en curso.');if(!user||profile?.role!=='admin')throw Error('Esta acción requiere una cuenta administradora.');busy=true;$('#sync-status').innerHTML='<span></span> Guardando…';try{const next=structuredClone(data);change(next);const validated=validateWorkspace(next),saved=await backend.saveWorkspace(validated,revision);data=validateWorkspace(saved.payload);revision=saved.revision;cache.clear();$('#sync-status').innerHTML='<span></span> Guardado en línea';return true;}finally{busy=false;if($('#sync-status').textContent.includes('Guardando'))$('#sync-status').innerHTML='<span></span> Revisa el guardado';}}
async function reloadData(){profile=await backend.loadProfile();if(profile.role!=='admin'){clearWorkspace();render();return;}if(busy)throw Error('Espera a que termine el guardado.');const saved=await backend.loadWorkspace();data=validateWorkspace(saved.payload);revision=saved.revision;cache.clear();render();$('#sync-status').innerHTML='<span></span> Actualizado';}
function errorMessage(e){return e?.message||'No pudimos completar la acción.';}
function showError(e){if($('#modal').open&&$('#form-error'))$('#form-error').innerHTML=`<div class="form-error" role="alert">${esc(errorMessage(e))}${e.conflict?'<br><button type="button" class="btn small" data-action="reload-after-conflict">Recargar registros</button>':''}</div>`;else toast(errorMessage(e));}
function showAuth(message='',mode='login'){
  $('#app-shell').hidden=true;$('#auth-screen').hidden=false;
  if(mode==='loading'){$('#auth-content').innerHTML='<div class="eyebrow">TU ESPACIO PERSONAL</div><h2>Preparando tus cuentas…</h2><p class="auth-description" role="status">Comprobando tu acceso y cargando los registros.</p>';return;}
  const configured=backend.isConfigured();
  if(mode==='link-error'){$('#auth-content').innerHTML=`<div class="auth-lock">${icon('shield')}</div><div class="eyebrow">REVISEMOS TU ENLACE</div><h2>Este enlace no está disponible.</h2><p class="auth-description">${esc(message)}</p>${authLinkMode==='invite'?'<p class="method-label">Solicita una invitación nueva y abre el enlace más reciente.</p>':button('Solicitar otro enlace','reset-view','primary')}<div style="margin-top:22px">${button('Volver al acceso','login-view','link')}</div>`;return;}
  if(mode==='signup-success'){$('#auth-content').innerHTML=`<div class="auth-lock">${icon('check')}</div><div class="eyebrow">UN NUEVO COMIENZO</div><h2>Revisa tu correo.</h2><p class="auth-description">Si el correo puede registrarse, recibirás un enlace para confirmar tu cuenta. Después podrás entrar con la contraseña que elegiste. Si ya tienes cuenta, inicia sesión o recupera tu contraseña.</p>${button('Volver al acceso','login-view','primary')}`;return;}
  if(mode==='signup'){$('#auth-content').innerHTML=`<div class="eyebrow">BIENVENIDO A CRISPY</div><h2>Crea tu cuenta.</h2><p class="auth-description">Elige tu acceso y cómo quieres que te llamemos.</p><form id="signup-form">${field('preferredName','¿Cómo quieres que te llame?',input('preferredName','required maxlength="40" autocomplete="nickname" placeholder="Tu nombre preferido"'))}${field('email','Correo electrónico',input('email','type="email" autocomplete="email" required'))}${field('password','Crea una contraseña',input('password','type="password" minlength="12" maxlength="128" autocomplete="new-password" required'))}${field('passwordConfirm','Repite la contraseña',input('passwordConfirm','type="password" minlength="12" maxlength="128" autocomplete="new-password" required'))}<p class="method-label">Usa al menos 12 caracteres. Se creará una cuenta de cliente; el acceso de administración lo asigna el propietario.</p><div id="auth-error" role="alert"></div><button class="btn primary auth-submit" type="submit">Crear mi cuenta ${icon('arrow')}</button></form>${button('Ya tengo cuenta','login-view','link')}`;return;}
  if(mode==='reset'){$('#auth-content').innerHTML=`<div class="eyebrow">RECUPERA TU ACCESO</div><h2>Volvamos a tus cuentas.</h2><p class="auth-description">Escribe el correo de tu cuenta. El enlace abrirá una pantalla para elegir una contraseña nueva.</p><form id="reset-form">${field('email','Correo electrónico',input('email','type="email" autocomplete="email" required'))}<div id="auth-error" role="status">${esc(message)}</div><button class="btn primary auth-submit" type="submit">Enviar enlace</button></form>${button('Volver al acceso','login-view','link')}`;return;}
  if(mode==='password'){$('#auth-content').innerHTML=`<div class="auth-lock">${icon('shield')}</div><div class="eyebrow">${passwordMode==='invite'?'TU CUENTA YA ESTÁ LISTA':'RECUPERA TU ACCESO'}</div><h2>${passwordMode==='invite'?'Crea tu contraseña.':'Elige tu nueva contraseña.'}</h2><p class="auth-description">${passwordUser?.email?'<strong>'+esc(passwordUser.email)+'</strong><br>':''}Usa al menos 12 caracteres. Al guardarla entrarás a tu espacio.</p><form id="password-form">${field('password','Nueva contraseña',`<div class="password-input">${input('password','type="password" minlength="12" maxlength="128" autocomplete="new-password" required')}<button type="button" data-action="toggle-password" aria-label="Mostrar contraseña">Ver</button></div>`)}${field('passwordConfirm','Repite la contraseña',input('passwordConfirm','type="password" minlength="12" maxlength="128" autocomplete="new-password" required'))}<div id="auth-error" role="alert">${esc(message)}</div><button class="btn primary auth-submit" type="submit">Guardar contraseña y entrar ${icon('arrow')}</button></form><div style="margin-top:22px">${button('Cancelar y salir','login-view','link')}</div>`;return;}
  $('#auth-content').innerHTML=`<div class="auth-lock">${icon('shield')}</div><div class="eyebrow">BIENVENIDO A TU ESPACIO</div><h2>Hola, Crispy.</h2><p class="auth-description">Inicia sesión para continuar con tus cuentas.</p><form id="login-form">${field('email','Correo electrónico',input('email',`type="email" autocomplete="username" required placeholder="Tu correo" ${configured?'':'disabled'}`))}${field('password','Contraseña',`<div class="password-input">${input('password',`type="password" autocomplete="current-password" required placeholder="Tu contraseña" ${configured?'':'disabled'}`)}<button type="button" data-action="toggle-password" aria-label="Mostrar contraseña">Ver</button></div>`)}<div class="auth-options">${button('Olvidé mi contraseña','reset-view','link','',''+(configured?'':'disabled'))}${button('Crear cuenta','signup-view','link','',''+(configured?'':'disabled'))}</div><div id="auth-error" role="alert">${esc(message)}</div><button class="btn primary auth-submit" type="submit" ${configured?'':'disabled'}>Ingresar a mi espacio ${icon('arrow')}</button></form><div class="auth-caption">${icon('shield')} Tu cuenta, tu espacio.</div>${!configured?'<div class="connection-note"><strong>Conexión pendiente</strong><p>El acceso estará disponible al conectar tu proyecto de Supabase. Todavía no se puede iniciar sesión.</p></div>':''}`;
}
function clearWorkspace(){data=emptyWorkspace();revision=0;cache.clear();}
function clearPrivateView(){user=null;profile=null;clearWorkspace();$('#content').innerHTML='';$('#nav').innerHTML='';$('#profile-email').textContent='';$('#modal').close();}
function clearSession(){clearPrivateView();backend.completePasswordFlow();passwordUser=null;recovery=false;authLinkMode=null;showAuth();}
function openPassword(entry){clearPrivateView();recovery=true;passwordMode=entry.mode;passwordUser=entry.user;authLinkMode=entry.mode;showAuth('','password');}
async function enterAccount(u){showAuth('','loading');const loadedProfile=await backend.loadProfile();clearWorkspace();if(loadedProfile.role==='admin'){const saved=await backend.loadWorkspace();data=validateWorkspace(saved.payload);revision=saved.revision;}profile=loadedProfile;user=u;$('#auth-screen').hidden=true;$('#app-shell').hidden=false;if((loadedProfile.role!=='admin'&&!['inicio','configuracion'].includes(route().page))||['recuperar','nueva-clave','acceso',''].includes(route().page))go('inicio');else render();}
async function logout(){if(busy)throw Error('Espera a que termine el guardado antes de cerrar sesión.');await backend.signOut();clearSession();toast('Sesión cerrada.');}
async function authSubmit(f){
  if(authBusy)return;authBusy=true;const submit=f.querySelector('[type="submit"]');submit.disabled=true;$('#auth-error').textContent='';let passwordSaved=false;
  try{
    const v=Object.fromEntries(new FormData(f));
    if(f.id==='login-form'){const u=await backend.signIn(v.email.trim(),v.password);await enterAccount(u);}
    else if(f.id==='signup-form'){if(!v.preferredName.trim())throw Error('Escribe cómo quieres que te llamemos.');if(v.password!==v.passwordConfirm)throw Error('Las contraseñas no coinciden.');if(v.password.length<12)throw Error('Usa al menos 12 caracteres.');const result=await backend.signUp(v.email.trim(),v.password,v.preferredName.trim());if(result.session&&result.user)await enterAccount(result.user);else showAuth('','signup-success');}
    else if(f.id==='reset-form'){await backend.requestPasswordReset(v.email.trim());$('#auth-error').textContent='Si el correo corresponde a una cuenta, recibirás un enlace. Abre el mensaje más reciente para crear tu nueva contraseña.';}
    else{
      if(!recovery||!passwordUser)throw Error('Abre primero un enlace válido de invitación o recuperación.');
      if(v.password!==v.passwordConfirm)throw Error('Las contraseñas no coinciden.');
      if(v.password.length<12)throw Error('Usa al menos 12 caracteres.');
      const u=await backend.updatePassword(v.password);passwordSaved=true;backend.completePasswordFlow();recovery=false;passwordUser=null;authLinkMode=null;
      const verified=u||await backend.currentUser();if(!verified)throw Error('Inicia sesión con la contraseña que acabas de guardar.');
      await enterAccount(verified);toast('Contraseña guardada. Bienvenido a tu espacio.');
    }
  }catch(e){
    const message=(passwordSaved?'Tu contraseña quedó guardada. ':'')+errorMessage(e);
    if(!$('#auth-error')||passwordSaved)showAuth(message);else $('#auth-error').textContent=message;
  }finally{authBusy=false;if(submit.isConnected)submit.disabled=false;}
}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;
  const publicHandlers={'signup-view':()=>showAuth('','signup'),'toggle-password':()=>{const p=$('#password');p.type=p.type==='password'?'text':'password';el.textContent=p.type==='password'?'Ver':'Ocultar';el.setAttribute('aria-label',p.type==='password'?'Mostrar contraseña':'Ocultar contraseña');},'reset-view':()=>{if(backend.isConfigured()){const email=$('#email')?.value||'';showAuth('','reset');$('#email').value=email;}},'login-view':async()=>{if(backend.isConfigured())await backend.signOut();clearSession();}};
  if(publicHandlers[a]){try{await publicHandlers[a]();}catch(err){if($('#auth-error'))$('#auth-error').textContent=errorMessage(err);else toast(errorMessage(err));}return;}if(!user)return;if(profile?.role!=='admin'&&!['close','logout','my-space'].includes(a)){toast('Esta opción está disponible para administradores.');return;}if(busy&&a!=='close'){toast('Espera a que termine el guardado.');return;}
  const handlers={close:closeModal,'my-space':()=>go('configuracion'),clients:()=>go('clientes'),payments:()=>go('movimientos'),client:()=>go('cliente/'+id),'new-client':()=>clientForm(),'edit-client':()=>clientForm(id),'new-loan':()=>loanForm(id),'edit-loan':()=>loanForm(null,id),'delete-loan':()=>deleteLoanDialog(id),'new-payment':()=>paymentForm(id),schedule:()=>showSchedule(id),export:exportData,csv:exportCsv,'payment-detail':()=>showPayment(id),filter:()=>{filter=el.dataset.value;render();},import:()=>$('#import-file').click(),logout,reload:async()=>{await reloadData();toast('Registros actualizados.');},'reload-after-conflict':async()=>{await reloadData();closeModal();toast('Registros actualizados. Vuelve a ingresar el cambio.');},'archive-client':()=>confirmArchive(id),'restore-client':()=>confirmArchive(id,true),'delete-client':()=>deleteClientDialog(id),'confirm-archive':async()=>{await mutate(d=>archiveClient(d,id,true));closeModal();render();toast('Cliente archivado. Su historial se conserva.');},'confirm-restore':async()=>{await mutate(d=>archiveClient(d,id,false));closeModal();render();toast('Cliente restaurado.');},reverse:()=>confirmDialog('¿Anular este abono?','Se conserva el registro y se recalculan los saldos y pagos posteriores.','confirm-reverse','Sí, anular',`data-id="${esc(id)}"`),'confirm-reverse':async()=>{await mutate(d=>{d.payments.find(p=>p.id===id).reversed=true;});closeModal();render();toast('Abono anulado e historial recalculado.');},'confirm-import':async()=>{await mutate(d=>Object.assign(d,pendingImport));pendingImport=null;closeModal();render();toast('Respaldo importado.');}};
  try{await handlers[a]?.();}catch(err){showError(err);}
});
document.addEventListener('input',e=>{handleMoneyInput(e);if(e.target.id==='search'){query=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);}if(e.target.closest('#loan-form'))updateSimulation();if(e.target.closest('#payment-form'))updatePaymentSummary();});
document.addEventListener('change',async e=>{if(e.target.closest('#loan-form')){updateLoanDates();updateSimulation();}if(e.target.closest('#payment-form'))updatePaymentSummary();if(e.target.id!=='import-file'||!user)return;const file=e.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error('El respaldo debe pesar menos de 5 MB.');pendingImport=validateWorkspace(JSON.parse(await file.text()),{allowLegacy:true});confirmDialog('¿Importar este respaldo?',`${pendingImport.clients.length} clientes, ${pendingImport.loans.length} préstamos y ${pendingImport.payments.length} abonos. Reemplazará tu cartera completa. Descarga primero un respaldo si quieres conservarla.`,'confirm-import','Sí, reemplazar e importar');}catch(err){toast(errorMessage(err));}e.target.value='';});
document.addEventListener('submit',async e=>{const f=e.target;if(!f.id)return;e.preventDefault();if(['login-form','reset-form','password-form','signup-form'].includes(f.id)){await authSubmit(f);return;}if(!user||busy)return;if(f.id==='profile-form'){const submit=f.querySelector('[type="submit"]');submit.disabled=true;try{profile=await backend.saveProfile(f.elements.preferredName.value);render();toast('Tu nombre quedó guardado.');}catch(err){const target=f.querySelector('#form-error');if(target)target.textContent=errorMessage(err);}finally{if(submit.isConnected)submit.disabled=false;}return;}if(profile?.role!=='admin')return;const submit=f.querySelector('[type="submit"]');submit.disabled=true;try{const v=Object.fromEntries(new FormData(f));let destination=location.hash.slice(1)||'inicio';
  if(f.id==='client-form'){const id=f.dataset.id||uid();await mutate(d=>{const c=d.clients.find(c=>c.id===id);if(!v.name.trim())throw Error('Escribe el nombre del cliente.');if(c)Object.assign(c,{name:v.name.trim(),phone:v.phone.trim(),note:v.note.trim()});else d.clients.push({id,name:v.name.trim(),phone:v.phone.trim(),note:v.note.trim(),createdAt:today(),archivedAt:null});});destination='cliente/'+id;}
  else if(f.id==='loan-form'){const existing=f.dataset.id?loan(f.dataset.id):null,c=client(v.clientId);if(!c||(c.archivedAt&&c.id!==existing?.clientId))throw Error('Selecciona un cliente activo.');const values={clientId:v.clientId,principal:parseCOP(v.principal),rate:+v.rate,lateRate:+v.lateRate,months:+v.months,start:v.start,note:v.note.trim(),firstDueDate:v.customDates?v.firstDueDate:null};if(existing)await mutate(d=>editLoan(d,existing.id,values));else await mutate(d=>{const l={id:uid(),...values,createdAt:new Date().toISOString()};if(!l.firstDueDate)delete l.firstDueDate;d.loans.push(l);});destination='cliente/'+v.clientId;}
  else if(f.id==='payment-form'){const p=candidatePayment(f);await mutate(d=>d.payments.push(p));destination='cliente/'+loan(p.loanId).clientId;}
  else if(f.id==='delete-loan-form'){const l=loan(f.dataset.id);if(!l)throw Error('No encontramos ese crédito.');destination='cliente/'+l.clientId;await mutate(d=>deleteLoan(d,f.dataset.id,v.confirmedDelete==='on'));}
  else if(f.id==='delete-form'){await mutate(d=>deleteClient(d,f.dataset.id,v.confirmedDelete==='on'));destination='clientes';}
  else return;
  closeModal();go(destination);toast(f.id==='payment-form'?'Abono guardado y distribuido automáticamente.':'Cambios guardados en línea.');
}catch(err){showError(err);}finally{if(submit.isConnected)submit.disabled=false;}});
window.addEventListener('hashchange',()=>{query='';filter='activos';$('#sidebar').classList.remove('open');if(user&&!recovery){render();window.scrollTo(0,0);}});
$('#menu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
$('#mobile-shade').addEventListener('click',()=>$('#sidebar').classList.remove('open'));
$('#profile').addEventListener('click',()=>go('configuracion'));
$('#help').addEventListener('click',()=>{if(profile?.role!=='admin'){modal('Tu cuenta de cliente','Bienvenido a Crispy Crédito.',`<div class="settings-body"><p>En Mi espacio puedes elegir cómo quieres que te llamemos. La consulta de historial se habilitará en una próxima actualización.</p>${button('Entendido','close','primary')}</div>`);return;}modal('Tus cuentas, claras','Cómo funciona Crispy Crédito.',`<div class="settings-body"><p>Registra clientes y préstamos. Al recibir un pago, ingresa su valor y fecha: se aplica por cuota a mora, intereses y capital.</p><p>En Mi espacio puedes ver las reglas de cálculo y descargar respaldos. Los clientes archivados conservan saldos e historial.</p><p>Los registros se guardan en Supabase. Puedes actualizar desde el botón ↻ para recoger cambios de otro dispositivo. La aplicación evita sobrescribir versiones más recientes.</p>${button('Entendido','close','primary')}</div>`);});
$('#modal').addEventListener('cancel',e=>{if(busy)e.preventDefault();});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
window.addEventListener('offline',()=>{if(user)$('#sync-status').innerHTML='<span></span> Sin conexión';});
window.addEventListener('online',()=>{if(user)$('#sync-status').innerHTML='<span></span> Conectado · actualiza ↻';});
async function boot(){
  const initialHref=location.href;showAuth('','loading');
  try{
    if(!backend.isConfigured()){showAuth();return;}
    await backend.onAuthChange(event=>{if(event==='SIGNED_OUT'&&!booting)clearSession();});
    const entry=await backend.authEntry(initialHref);
    if(entry.kind==='password')openPassword(entry);
    else if(entry.kind==='link-error'){clearPrivateView();recovery=false;authLinkMode=entry.mode;showAuth(entry.message,'link-error');}
    else if(entry.kind==='account')await enterAccount(entry.user);
    else showAuth();
  }catch(e){clearPrivateView();showAuth(errorMessage(e));}
  finally{booting=false;}
}
boot();
